import { expect, test } from './browser-test.ts';
import { EXAMPLE_CODE } from '../src/game/game.fixture.ts';
import { DealControl, ReproductionControl } from '../src/game/controls/control-labels.ts';
import { SNAPSHOT_VERSION } from '../src/game/snapshot.ts';
import { SelectionKind } from '../src/game/selection.ts';
import { boardCode, parseBoardCode } from '../src/game/deck.ts';
import { loadFixedBoard, PHONE } from './game-fixture.ts';
import { boardGaps } from './focus-bounds.ts';
import { moveKeyboardTo } from './accessibility-tree.ts';
import type { Page } from '@playwright/test';

const SIZE = 16;
// Row 7, column 11 sits past the right edge of a phone board scrolled back to its start.
const REMEMBERED = 6 * SIZE + 10;
// Row 15, column 16 sits past the right and bottom edges of that board.
const FAR = 14 * SIZE + 15;
const EXAMPLE_SIZE = parseBoardCode(EXAMPLE_CODE)?.size ?? 0;

async function scrollBoardToStart(page: Page): Promise<void> {
  await page.locator('.board-viewport').evaluate((viewport) => viewport.scrollTo(0, 0));
  await page.evaluate(() => new Promise((ready) => requestAnimationFrame(ready)));
}

test('Tab and Shift+Tab bring the remembered card in with nearest alignment', async ({ page }) => {
  await page.setViewportSize(PHONE);
  await loadFixedBoard(page);
  await page.getByLabel(DealControl.size, { exact: true }).selectOption(String(SIZE));
  const restart = page.getByRole('button', { name: DealControl.restart, exact: true });
  await restart.focus();
  await page.keyboard.press('Tab');
  await moveKeyboardTo(page, REMEMBERED, SIZE);
  const card = page.locator('.card').nth(REMEMBERED);
  for (const enter of ['Shift+Tab', 'Tab']) {
    if (enter === 'Shift+Tab') await page.keyboard.press('Tab');
    else await restart.focus();
    await scrollBoardToStart(page);
    await page.keyboard.press(enter);
    await expect(card).toBeFocused();
    const gaps = await boardGaps(card);
    expect(gaps.right, `I13 ${enter} enters with nearest alignment`).toBeCloseTo(gaps.margin, 0);
  }
});

test('Resume returns focus to the remembered card with nearest alignment', async ({ page }) => {
  await page.setViewportSize(PHONE);
  await loadFixedBoard(page);
  await page.locator('summary').click();
  const paused = {
    version: SNAPSHOT_VERSION,
    boardCode: boardCode(SIZE, 1),
    matched: [],
    selection: { kind: SelectionKind.one, index: 0 },
    moves: 0,
    elapsedMs: 0,
    started: true,
  };
  await page.getByLabel(ReproductionControl.snapshot, { exact: true }).fill(JSON.stringify(paused));
  await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
  await page.locator('.card').first().focus();
  await moveKeyboardTo(page, FAR, SIZE);
  const card = page.locator('.card').nth(FAR);
  await expect(card).toBeFocused();
  await scrollBoardToStart(page);
  await page.getByRole('button', { name: ReproductionControl.resume, exact: true }).click();
  await expect(card).toBeFocused();
  const gaps = await boardGaps(card);
  expect(gaps.right, 'I13 Resume returns with nearest alignment').toBeCloseTo(gaps.margin, 0);
  expect(gaps.bottom, 'I13 Resume returns with nearest alignment').toBeCloseTo(gaps.margin, 0);
});

test('every keyboard move after a pointer click shows the focus outline', async ({ page }) => {
  await loadFixedBoard(page);
  const cards = page.locator('.card');
  await cards.nth(5).click();
  for (const [key, index] of [
    ['ArrowRight', 6],
    ['ArrowDown', 6 + EXAMPLE_SIZE],
    ['ArrowLeft', 5 + EXAMPLE_SIZE],
    ['ArrowUp', 5],
  ] as const) {
    await page.keyboard.press(key);
    await expect(cards.nth(index)).toBeFocused();
    await expect(cards.nth(index), `V16 outline after ${key}`).toHaveCSS('outline-style', 'solid');
    await expect(cards.nth(index), `V16 outline after ${key}`).toHaveCSS('outline-width', '3px');
  }
});
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { test } from 'vitest';
import { sourceFiles } from './source-files.ts';
import { isJsonObject } from '../src/game/saved-format.ts';

test('packages and lock use the reviewed exact versions and strict separate compiler projects', async () => {
  const pkg: unknown = JSON.parse(await readFile('package.json', 'utf8'));
  const expected: unknown = JSON.parse(
    await readFile(new URL('./package.fixture.json', import.meta.url), 'utf8'),
  );
  assert.ok(
    isJsonObject(pkg) &&
      isJsonObject(pkg.dependencies) &&
      isJsonObject(pkg.devDependencies) &&
      isJsonObject(expected),
  );
  const installed = { ...pkg.dependencies, ...pkg.devDependencies };
  assert.deepEqual(Object.keys(pkg.dependencies).sort(), ['react', 'react-dom']);
  for (const [name, version] of Object.entries(expected)) assert.equal(installed[name], version);
  const lock: unknown = JSON.parse(await readFile('package-lock.json', 'utf8'));
  assert.ok(isJsonObject(lock) && isJsonObject(lock.packages));
  const locked = lock.packages[''];
  assert.ok(isJsonObject(locked));
  assert.deepEqual(locked.dependencies, pkg.dependencies);
  assert.deepEqual(locked.devDependencies, pkg.devDependencies);
  assert.equal(pkg.type, 'module');
  const config: unknown = JSON.parse(await readFile('tsconfig.base.json', 'utf8'));
  assert.ok(isJsonObject(config) && isJsonObject(config.compilerOptions));
  for (const key of [
    'strict',
    'noUncheckedIndexedAccess',
    'exactOptionalPropertyTypes',
    'verbatimModuleSyntax',
    'erasableSyntaxOnly',
  ])
    assert.equal(config.compilerOptions[key], true);
  for (const project of ['app', 'node', 'e2e'])
    assert.ok(await readFile(`tsconfig.${project}.json`, 'utf8'));
  assert.ok(isJsonObject(pkg.scripts));
  assert.equal(
    pkg.scripts.typecheck,
    'tsc -p tsconfig.app.json && tsc -p tsconfig.node.json && tsc -p tsconfig.e2e.json',
    'T07 every compiler project',
  );
  assert.equal(pkg.scripts.test, 'vitest run', 'T02 Vitest runs unit tests');
});

test('authored TypeScript stays small, uses static ESM and rejects unsafe type escapes', async () => {
  const files = (await Promise.all(['src', 'scripts', 'tests', 'art'].map(sourceFiles))).flat();
  for (const file of files.filter((file) => /\.tsx?$/.test(file.path))) {
    assert.ok(file.text.trimEnd().split(/\r?\n/).length <= 200, file.path);
    assert.doesNotMatch(file.text, /@ts-(?:ignore|nocheck|expect-error)/);
    assert.doesNotMatch(
      file.text,
      /\bany\b|\bas\s+(?:[A-Z{]|unknown\b|number\b|string\b)|\bimport\s*\(|\brequire\s*\(/,
    );
  }
});

test('the game core has no browser effects and the shipped source has no audio or diagnostic entry', async () => {
  const files = await sourceFiles('src');
  const core = new Set(['deck.ts', 'game.ts', 'snapshot.ts', 'snapshot-selection.ts', 'replay.ts']);
  for (const file of files.filter((file) => !/\.(test|fixture)\./.test(file.path))) {
    assert.doesNotMatch(
      file.text,
      /AudioContext|new Audio\b|<audio|<canvas|fetch\(|XMLHttpRequest|window\.[a-zA-Z]*[Dd]eck/,
    );
    if (core.has(file.path.split(/[\\/]/).at(-1) ?? ''))
      assert.doesNotMatch(
        file.text,
        /\b(window|document|localStorage|performance|crypto|Date)\b|Math\.random/,
      );
    assert.doesNotMatch(file.text, /fixture|face-sheet|test-results/);
  }
});
